local GachaponMember = Class('GachaponMember')


function GachaponMember:__init()
    ---@type integer @ 选中的卡池索引
    self._selectIndex = nil
    ---@type integer @ 当前卡池类型
    self._poolType = nil
    ---@type integer @ 阵营卡池id
    self._campId = nil
end


function GachaponMember:__delete()
    self._selectIndex = nil
    self._poolType    = nil
