end


function GachaponMember:Awake()
    self.controller.IsAutoHandleNavBar = false

    SetButtonAction(self.ButtonClose, function()
        CfUtils.DialogClose(self.controller)
    end)
    SetButtonAction(self.CloseEmpty, function()
        CfUtils.DialogClose(self.controller)
    end)
end


function GachaponMember:OnInitialize()
    return CoWaitDo(function()
        local initParams  = self.controller.Argument.parameters
        self._selectIndex = checkInt(initParams.SelectIndex)
        self._poolType    = checkInt(initParams.PoolType)
        self._campId      = checkInt(initParams.CampId)
    end)
end


function GachaponMember:OnFinalize()
    return CoWaitDo(function()
        self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
        self:Delete()
    end)
end


function GachaponMember:OnShow()
    return CoWaitDo(function()
        local gachaponComp = GachaponUtils.GetGachaponComp()
        self:InitPool(gachaponComp.AllGachapon[self._selectIndex])
    end)
end


---@param pool GachaponDojo
function GachaponMember:InitPool(pool)
    ---@param t GachaponPreviewDojo[]
    ---@return GachaponPreviewDojo[]
    local function unique(t)
        local cacheMap  = {}
        local pureList  = {}
        local pureIndex = 1
        for _, previewDojo in pairs(t) do
            if GachaponUtils.IsCardGoods(previewDojo.itemId) then
                if not cacheMap[previewDojo.itemId] then
                    pureList[pureIndex] = previewDojo
                    pureIndex = pureIndex + 1
                    cacheMap[previewDojo.itemId] = true
                end
            else
                -- 碎片不去重合并，因为会有：xx碎片x1，xx碎片x5，xx碎片x10，这种相同id不同数量的展示
                pureList[pureIndex] = previewDojo
                pureIndex = pureIndex + 1
            end
        end
        return pureList
    end
    if GachaponUtils.IsOverseaCampType(self._poolType) then
        local activityData = checkTable(pool.activity)
        local previewDatas = checkTable(checkTable(activityData.campsPreview)[tostring(self._campId)])
        local previewDojos = {}
        for index, data in ipairs(previewDatas) do
            previewDojos[index] = GachaponPreviewDojo.New():Fill(data)
        end
        self:InitMember(unique(previewDojos), pool)
    else
        self:InitMember(unique(pool.preview), pool)
    end
end


---@param members GachaponPreviewDojo[]
---@param pool GachaponDojo
function GachaponMember:InitMember(members, pool)
    ---@type table<integer, table> @ key：按照显示品质分组
    local memberMap = {}
    for i, previewDojo in ipairs(members) do
        local member, rare = self:GetMembersData(previewDojo.itemId)
        local displayRare  = tostring(previewDojo.rareGroup) -- 品质分组按照返回的数据，不根据物品品质分组了
        -- 按照品质分组记录
        if not isSet(memberMap, displayRare) then
            memberMap[displayRare] = {}
        end
        table.insert(memberMap[displayRare], {
            previewVo   = member,
            previewRare = rare,
            previewDojo = previewDojo,
            displayRare = displayRare,
        })
    end

    CfUtils.SetActive(self.MemberBlock,false)
    -- 装备规则和卡池说明 分开调用
    if GachaponUtils.IsEquipType(self._poolType) then
        -- 已经砍了
    else
        local descrText  = pool.poolDesc
        local poolRates  = pool.rates
        local ratesIndex = checkTable(pool.ratesIndex)
        ------------------------------------------------- [阵营卡池]
        if GachaponUtils.IsOverseaCampType(self._poolType) then
            local activityData = checkTable(pool.activity)
            descrText  = tostring(checkTable(activityData.campsPoolDesc)[tostring(self._campId)])
            poolRates  = clone(checkTable(activityData.campsRates)[tostring(self._campId)] or {})
            ratesIndex = checkTable(activityData.campsRatesIndex)[tostring(self._campId)] or {}
            for k, v in pairs(poolRates) do
                poolRates[k] = checkNumber(v) * 100
            end
        ------------------------------------------------- [光暗卡池]
        elseif GachaponUtils.IsOverseaLightDarkType(self._poolType) then
            ---@type table<integer, table> @ key：按照显示品质分组
            local propMemberMap = {}
            for _, propsPreviewDojo in ipairs(pool.extraPreview) do
                local member, rare = self:GetMembersData(propsPreviewDojo.itemId)
                local displayRare  = tostring(propsPreviewDojo.rareGroup) -- 品质分组按照返回的数据，不根据物品品质分组了
                -- 按照品质分组记录
                if not isSet(propMemberMap, displayRare) then
                    propMemberMap[displayRare] = {}
                end
                table.insert(propMemberMap[displayRare], {
                    previewVo   = member,
                    previewRare = rare,
                    previewDojo = propsPreviewDojo,
                    displayRare = displayRare,
                })
            end

            local mergerMembers = {}
            for _, memberList in pairs(memberMap) do
                for _, memberData in ipairs(memberList) do
                    table.insert(mergerMembers, memberData)
                end
            end

            local mergerProps = {}
            for _, memberList in pairs(propMemberMap) do
                for _, memberData in ipairs(memberList) do
                    table.insert(mergerProps, memberData)
                end
            end

            poolRates  = {100, 100} -- 全部卡牌100%，全部道具100%
            ratesIndex = {1, 2}     -- 1：卡牌、碎片，2：货币、道具
            memberMap  = {
                ['1'] = mergerMembers,
                ['2'] = mergerProps,
            }
        end
        CfUtils.SetActive(self.ScrollBar, true)
        -- update descr
        self:InitEnsurance(descrText)
        cs_coroutine.yield_return(Yielders.EndOfFrame)
        -- update members
        for _, rare in ipairs(ratesIndex) do
            local memberNodeGo = CfUtils.InstantiateGo(self.MemberBlock, self.MemberGroup)
            local memberNodeRt = CfUtils.GetRectTransform(memberNodeGo)
            CfUtils.SetActive(memberNodeGo, true)
            self:UpdateMemberBlock(memberNodeRt, memberMap[tostring(rare)], rare, poolRates[checkInt(rare)] or poolRates[tostring(rare)])
        end
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
        CfUtils.SetCanvasGroupAlpha(self.ScrollBar.gameObject , 1)
    end
end


---@param goodsId integer
---@return GoodsVo|CardVo, integer
function GachaponMember:GetMembersData(goodsId)
    local member , rare
    local goodsType = GoodsUtils.GetIdType(goodsId)
    if goodsType == Constants.IDType.CharacterCard then
        ---@type CardVo
        member = cardConfMgr:GetCardByRefId(goodsId) or {}
        rare = checkInt(member.rare)
    else
        ---@type GoodsVo
        member = goodsConfMgr:GetGoodsVoById(goodsId) or {}
        rare = checkInt(member.quality)
    end
    return member, rare
end


---@param memberBlockTrans UnityEngine.RectTransform @ 卡牌头像节点
---@param members table[] @ 全部卡牌列表
---@param rareId integer @ 品质id
---@param rateValue number @ 品质概率值
function GachaponMember:UpdateMemberBlock(memberBlockTrans, members, rareId, rateValue)
    local titleGroupNode  = nil
    local titleGroupNode1 = memberBlockTrans:Find('TittleGroup')
    local titleGroupNode2 = memberBlockTrans:Find('TittleGroup2')
    local memberBlockRate = checkInt(SwitchRareState[checkInt(rareId)])
    if GachaponUtils.IsOverseaLightDarkType(self._poolType) then
        memberBlockRate = rareId
        titleGroupNode  = titleGroupNode2
        CfUtils.SetActive(titleGroupNode1, false)
        CfUtils.SetActive(titleGroupNode2, true)
    else
        titleGroupNode = titleGroupNode1
        CfUtils.SetActive(titleGroupNode1, true)
        CfUtils.SetActive(titleGroupNode2, false)
    end

    -- 品质标题背景条
    CfUtils.SetUISwitchImage(titleGroupNode:Find('bg'), memberBlockRate)

    -- 品质标题字
    if GachaponUtils.IsOverseaLightDarkType(self._poolType) then
        CfUtils.SetUISwitchText(titleGroupNode:Find('rare'), rareId)
    else
        CfUtils.FillText(titleGroupNode:Find('rare'), CfUtils.GetRareText(rareId))
    end

    -- 品质概率值
    local rateTxtNode = titleGroupNode:Find('TextProbability')
    CfUtils.FillText(rateTxtNode, string.fmt('%1%', tostring(rateValue)))
    CfUtils.SetUISwitchText(rateTxtNode, memberBlockRate)
    CfUtils.SetActive(rateTxtNode, not GachaponUtils.IsOverseaLightDarkType(self._poolType))
    
    -- 头像容器
    local content = memberBlockTrans:Find('Content')
    local voCount = #checkTable(members)
    if voCount > 0 then
        cs_coroutine.yield_return(Yielders.EndOfFrame)
        GachaponUtils.ResizeContent(content, voCount, self.RoleCell.gameObject)
        table.sort(members, function(aMemberData, bMemberData)
            ---@type GoodsVo | CardVo
            local aCardVo = aMemberData.previewVo
            ---@type GoodsVo | CardVo
            local bCardVo = bMemberData.previewVo
            ---@type GachaponPreviewDojo
            local aPreviewDojo = aMemberData.previewDojo
            ---@type GachaponPreviewDojo
            local bPreviewDojo = bMemberData.previewDojo
            local aPriority = 0
            local bPriority = 0
            local aItemRare = aMemberData.previewRare
            local bItemRare = bMemberData.previewRare
            aPriority = aPriority + (aPreviewDojo.isUp == 1 and 10000 or 0)
            bPriority = bPriority + (bPreviewDojo.isUp == 1 and 10000 or 0)
            aPriority = aPriority + (aCardVo.roleId ~= nil and 1000 or 0)  -- 卡牌 > 道具
            bPriority = bPriority + (bCardVo.roleId ~= nil and 1000 or 0)  -- 卡牌 > 道具
            aPriority = aPriority + (aItemRare > bItemRare and 100 or 0)
            bPriority = bPriority + (bItemRare > aItemRare and 100 or 0)
            aPriority = aPriority + (aCardVo.refId == bCardVo.refId and aPreviewDojo.itemNum < bPreviewDojo.itemNum and 1 or 0) -- 道具类
            bPriority = bPriority + (bCardVo.refId == aCardVo.refId and bPreviewDojo.itemNum < aPreviewDojo.itemNum and 1 or 0) -- 道具类
            aPriority = aPriority + (aCardVo.refId >= bCardVo.refId and 1 or 0)
            bPriority = bPriority + (bCardVo.refId >= aCardVo.refId and 1 or 0)
            return aPriority > bPriority
        end)
        for i, aMemberData in ipairs(members) do
            local roleCellTf = content:GetChild(i - 1)
            roleCellTf.name  = 'RoleCell_' .. i
            self:UpdateCardCell(roleCellTf, aMemberData.previewVo, aMemberData.previewDojo)
        end
    else
        CfUtils.SetActive(content, false)
    end
end


---@param trans UnityEngine.Transform
---@param cardVo GoodsVo | CardVo
---@param previewDojo GachaponPreviewDojo
function GachaponMember:UpdateCardCell(roleCellTrans, cardVo, previewDojo)
    local cardHeadNodeGo = roleCellTrans:Find('CommonSmallHeadNode')
    local goodsNodeGo    = roleCellTrans:Find('GoodNode')

    ---@type CardHeadNode
    local cardHeadNodeEnv = CfUtils.GetLuaScr(cardHeadNodeGo, Constants.UILuaTablePath.CardHeadNode)

    ---@type GoodNodeMB
    local goodsNodeEnv = CfUtils.GetLuaScr(goodsNodeGo, Constants.UILuaTablePath.GoodNodeMB)

    -- 卡牌头像
    if cardVo.roleId ~= nil then
        CfUtils.SetActive(goodsNodeGo, false)
        CfUtils.SetActive(cardHeadNodeGo, true)

        local cardDojo = CardUtils.GenerateCustomById(cardVo.refId)
        cardHeadNodeEnv:FreshNode(cardDojo, false, 0)
        cardHeadNodeEnv:SetRookieStatus(true)
        cardHeadNodeEnv:SetBottomImageStatus(false)
        cardHeadNodeEnv:SetCallBack(function(id, index)
            cs_coroutine.start(function()
                CfUtils.DialogClose(self.controller)
                cs_coroutine.yield_return(Yielders.EndOfFrame)
                GachaponShared.RecordJump = self._selectIndex - 1
                GachaponUtils.OpenDetail(cardVo.roleId)
            end)
        end)

    -- 道具图标
    else
        CfUtils.SetActive(goodsNodeGo, true)
        CfUtils.SetActive(cardHeadNodeGo, false)

        local goodsId = cardVo.refId
        goodsNodeEnv:Reload({goodsId = goodsId, isShowNo = true, text = string.fmt('x%1', tostring(previewDojo.itemNum))})
        goodsNodeEnv:SetClickCallback(function()
            local goodsVo = goodsConfMgr:GetGoodsVoById(goodsId)
            GameUtils.ShowCommonTipsBoard(goodsNodeGo, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id, false)
        end)
    end

    -- up状态标识
    local isCardUp = previewDojo.isUp == 1
    CfUtils.SetActive(roleCellTrans:Find('ImgUp'), isCardUp)

    -- 概率文本
    CfUtils.FillText(roleCellTrans:Find('Probability/TextNumber'), string.format('%0.4f%%', checkNumber(previewDojo.displayNum)))

    -- 是否可互动
    local isInteractive = cardVo.defaultSkin ~= nil and IdolLive3D_Utils.GetLive3DCardVoRow(cardVo.defaultSkin)
    CfUtils.SetActive(roleCellTrans:Find('ImgInteract'), isInteractive)
end


---@param desc string
function GachaponMember:InitEnsurance(desc)
    CfUtils.SetActive(self.EnsuranceMain, false)
    CfUtils.FillText(self.EnsuranceMain, desc)
    cs_coroutine.yield_return(Yielders.EndOfFrame)
    CfUtils.SetActive(self.EnsuranceMain, true)
    CfUtils.FillText(self.EnsuranceMain2, localize('战斗员获得概率显示四舍五入至小数点后4位。'))
end


return GachaponMember
